from __future__ import annotations

import enum
from typing import Any


class CheckKind(enum.Enum):
    """The kinds of checks that are run against each package change.

    The enum ``value`` is the lowercase string used when serializing.
    """

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(enum.Enum):
    """The outcome of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


class CheckResult:
    """Represents the result of a single check."""

    def __init__(self, status: CheckStatus, details: str) -> None:
        """Initialize a check result."""
        self.status = status
        self.details = details

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation."""
        return {"status": self.status.value, "details": self.details}

    def __repr__(self) -> str:
        """Return a debug representation."""
        return f"CheckResult(status={self.status!r}, details={self.details!r})"


class PackageChange:
    """Represents a single package version change detected in a diff."""

    def __init__(
        self,
        name: str,
        old_version: str | None,
        new_version: str,
        checks: dict[CheckKind, CheckResult] | None = None,
        repo_url: str | None = None,
    ) -> None:
        """Initialize a package change."""
        self.name = name
        self.old_version = old_version
        self.new_version = new_version
        self.checks: dict[CheckKind, CheckResult] = checks if checks is not None else {}
        self.repo_url = repo_url

    @property
    def needs_agent(self) -> bool:
        """Return True if at least one check needs an agent to resolve."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT
            for result in self.checks.values()
        )

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation."""
        return {
            "name": self.name,
            "old_version": self.old_version,
            "new_version": self.new_version,
            "repo_url": self.repo_url,
            "needs_agent": self.needs_agent,
            "checks": {
                kind.value: result.to_dict() for kind, result in self.checks.items()
            },
        }

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"PackageChange(name={self.name!r}, old_version={self.old_version!r}, "
            f"new_version={self.new_version!r})"
        )


class CheckRunResult:
    """Represents the result of running all checks for a PR."""

    def __init__(
        self, pr_number: int, packages: list[PackageChange] | None = None
    ) -> None:
        """Initialize a check run result."""
        self.pr_number = pr_number
        self.packages: list[PackageChange] = packages if packages is not None else []

    @property
    def needs_agent(self) -> bool:
        """Return True if any contained package needs an agent to resolve."""
        return any(package.needs_agent for package in self.packages)

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation of the run.

        Includes the rendered PR comment, an aggregate ``needs_agent`` flag,
        a per-kind ``checks`` summary and a convenience boolean for every
        lowercase check kind name (e.g. ``repo_public``).
        """
        # Imported lazily to avoid a circular import with the render module.
        from .render import render_comment

        # Per-kind summary: True when any package needs an agent for that kind.
        kind_summary = {
            kind.value: any(
                package.checks.get(kind)
                and package.checks[kind].status is CheckStatus.NEEDS_AGENT
                for package in self.packages
            )
            for kind in CheckKind
        }

        result: dict[str, Any] = {
            "pr_number": self.pr_number,
            "needs_agent": self.needs_agent,
            "rendered_comment": render_comment(self),
            "checks": kind_summary,
            "packages": [package.to_dict() for package in self.packages],
        }
        # Expose each check kind at the top level as well.
        result.update(kind_summary)
        return result

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"CheckRunResult(pr_number={self.pr_number!r}, "
            f"packages={self.packages!r})"
        )
