from __future__ import annotations

import fnmatch
import re

from .models import PackageChange

# Only files whose basename matches this glob are inspected.
_TRACKED_GLOB = "requirements*.txt"

# Matches ``name==version`` optionally followed by extras, e.g. ``Foo[bar]==1.0``.
_REQUIREMENT_RE = re.compile(
    r"^(?P<name>[A-Za-z0-9][A-Za-z0-9._-]*)"
    r"(?:\[[^\]]*\])?"
    r"\s*==\s*"
    r"(?P<version>[^\s;]+)"
)


def _canonical_name(name: str) -> str:
    """Normalize a project name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _basename(path: str) -> str:
    """Return the final path component of a diff path."""
    return path.rsplit("/", 1)[-1]


def _is_tracked(path: str) -> bool:
    """Return True if the given path points to a tracked requirements file."""
    return fnmatch.fnmatch(_basename(path), _TRACKED_GLOB)


def _diff_target_path(line: str) -> str:
    """Extract the file path from a ``+++`` diff header line."""
    # Strip the ``+++ `` prefix and any trailing tab-delimited timestamp.
    path = line[4:].split("\t", 1)[0].strip()
    # Strip a leading ``b/`` (or ``a/``) prefix used by git diffs.
    if path.startswith(("a/", "b/")):
        path = path[2:]
    return path


def _parse_requirement(text: str) -> tuple[str, str] | None:
    """Parse a requirement line into a normalized (name, version) tuple.

    Returns None for comment lines, blank lines, or lines that do not pin a
    version with ``==``. Inline comments are stripped before parsing.
    """
    # Drop inline comments.
    text = text.split("#", 1)[0].strip()
    if not text:
        return None
    match = _REQUIREMENT_RE.match(text)
    if match is None:
        return None
    return _canonical_name(match.group("name")), match.group("version")


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff and return the package changes it contains.

    Only changes within files matching ``requirements*.txt`` are considered.
    Package names are normalized per PEP 503. Newly added packages get
    ``old_version=None``. Lines with no version change are ignored.
    """
    changes: list[PackageChange] = []

    tracked = False
    removed: dict[str, str] = {}
    added: dict[str, str] = {}

    def flush() -> None:
        """Emit package changes accumulated for the current file."""
        for name, new_version in added.items():
            old_version = removed.get(name)
            if old_version == new_version:
                # Version did not change; ignore.
                continue
            changes.append(
                PackageChange(
                    name=name,
                    old_version=old_version,
                    new_version=new_version,
                )
            )
        removed.clear()
        added.clear()

    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            # A new file target begins; flush the previous file's changes.
            flush()
            path = _diff_target_path(line)
            tracked = path != "/dev/null" and _is_tracked(path)
            continue
        if line.startswith("--- "):
            # Old-file header line; nothing to do here.
            continue
        if line.startswith("diff --git"):
            # New file section header; wait for the ``+++`` line to decide.
            flush()
            tracked = False
            continue
        if line.startswith("@@"):
            continue
        if not tracked:
            continue
        if line.startswith("+"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                added[parsed[0]] = parsed[1]
        elif line.startswith("-"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                removed[parsed[0]] = parsed[1]

    flush()
    return changes
