from __future__ import annotations

from typing import Any
from urllib.parse import urlparse

import requests

_TIMEOUT = 30

# Hostnames that are accepted as code-hosting repositories. The comparison is
# exact to reject domain-suffix lookalikes such as ``github.com.evil.com``.
_CODE_HOST_HOSTNAMES = frozenset(
    {"github.com", "www.github.com", "gitlab.com", "www.gitlab.com"}
)

# Project-URL keys that are preferred when looking for a repository URL.
_REPO_URL_KEYS = ("Source", "Repository")


class PypiPackageInfo:
    """Holds information fetched from PyPI for a specific package version."""

    def __init__(
        self,
        project_urls: dict,
        repo_url: str | None,
        file_provenance_urls: list[str],
        found: bool,
    ) -> None:
        """Initialize the package info."""
        self.project_urls = project_urls
        self.repo_url = repo_url
        self.file_provenance_urls = file_provenance_urls
        self.found = found


class ProvenanceResult:
    """Holds the result of a provenance/attestation check."""

    def __init__(
        self,
        has_attestation: bool,
        publisher_kind: str | None,
        recognized_publisher: bool,
        detail: str,
    ) -> None:
        """Initialize the provenance result."""
        self.has_attestation = has_attestation
        self.publisher_kind = publisher_kind
        self.recognized_publisher = recognized_publisher
        self.detail = detail


def _strip_control_chars(value: str) -> str:
    """Remove backtick and newline characters from a string."""
    return value.replace("`", "").replace("\n", "").replace("\r", "").strip()


def _fetch_json(url: str) -> tuple[str, Any]:
    """Fetch JSON from a URL.

    Returns a ``(status, data)`` tuple where status is one of ``"ok"``,
    ``"notfound"`` (HTTP 404) or ``"fail"`` (network error, 5xx, other
    non-200 status, or invalid JSON).
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return "fail", None

    if response.status_code == 404:
        return "notfound", None
    if response.status_code != 200:
        return "fail", None

    try:
        return "ok", response.json()
    except ValueError:
        return "fail", None


def _is_code_host_url(value: Any) -> bool:
    """Return True if the value is an HTTP(S) URL on a known code host."""
    if not isinstance(value, str):
        return False
    try:
        parsed = urlparse(value.strip())
    except ValueError:
        return False
    if parsed.scheme not in ("http", "https"):
        return False
    hostname = (parsed.hostname or "").lower()
    return hostname in _CODE_HOST_HOSTNAMES


def _select_repo_url(project_urls: Any) -> str | None:
    """Select a repository URL from a project's URL mapping.

    Prefers the ``Source``/``Repository`` keys, then scans all values for a
    URL on a recognized code host. Returns None when no valid URL is found.
    """
    if not isinstance(project_urls, dict):
        return None

    for key in _REPO_URL_KEYS:
        value = project_urls.get(key)
        if _is_code_host_url(value):
            return _strip_control_chars(value)

    for value in project_urls.values():
        if _is_code_host_url(value):
            return _strip_control_chars(value)

    return None


def _build_info(
    name: str, version: str, data: dict, *, found: bool
) -> PypiPackageInfo:
    """Build a PypiPackageInfo from a PyPI JSON response."""
    info = data.get("info") if isinstance(data, dict) else None
    project_urls = {}
    if isinstance(info, dict):
        raw = info.get("project_urls")
        if isinstance(raw, dict):
            project_urls = raw

    repo_url = _select_repo_url(project_urls)

    file_provenance_urls: list[str] = []
    if found:
        urls = data.get("urls")
        if isinstance(urls, list) and urls:
            first = urls[0]
            filename = first.get("filename") if isinstance(first, dict) else None
            if filename:
                # The urls[].provenance field is deliberately ignored; the
                # integrity URL is always constructed from the filename.
                file_provenance_urls = [
                    f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance"
                ]

    return PypiPackageInfo(
        project_urls=project_urls,
        repo_url=repo_url,
        file_provenance_urls=file_provenance_urls,
        found=found,
    )


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata from PyPI for the given name and version."""
    versioned_url = f"https://pypi.org/pypi/{name}/{version}/json"
    status, data = _fetch_json(versioned_url)
    if status == "ok":
        return _build_info(name, version, data, found=True)

    # Fall back to the latest-version endpoint (either the version was not
    # found, or the versioned endpoint failed). The package is not confirmed
    # at this version, so found=False and no provenance URLs are produced.
    latest_url = f"https://pypi.org/pypi/{name}/json"
    latest_status, latest_data = _fetch_json(latest_url)
    if latest_status == "ok":
        return _build_info(name, version, latest_data, found=False)

    return PypiPackageInfo(
        project_urls={},
        repo_url=None,
        file_provenance_urls=[],
        found=False,
    )


def check_provenance(pkg: PypiPackageInfo) -> ProvenanceResult:
    """Check PEP 740 provenance attestations for a package."""
    if not pkg.found:
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail=(
                "Package version could not be located on PyPI; "
                "cannot verify provenance."
            ),
        )

    for url in pkg.file_provenance_urls:
        status, data = _fetch_json(url)
        if status != "ok":
            # 404 (and any transient failure) -> try the next URL.
            continue

        bundles = data.get("attestation_bundles") if isinstance(data, dict) else None
        if not isinstance(bundles, list) or not bundles:
            continue

        for bundle in bundles:
            if not isinstance(bundle, dict):
                continue
            publisher = bundle.get("publisher")
            if not isinstance(publisher, dict):
                continue
            kind = publisher.get("kind")
            if kind is None:
                # Entries without a kind are skipped.
                continue
            publisher_kind = _strip_control_chars(str(kind))
            recognized = publisher_kind == "GitHub"
            if recognized:
                detail = (
                    "PEP 740 provenance attestation present, published by "
                    "a recognized publisher (GitHub)."
                )
            else:
                detail = (
                    "PEP 740 provenance attestation present, but published by "
                    f"an unrecognized publisher ({publisher_kind})."
                )
            return ProvenanceResult(
                has_attestation=True,
                publisher_kind=publisher_kind,
                recognized_publisher=recognized
