from __future__ import annotations

from .models import CheckKind, CheckRunResult, CheckStatus, PackageChange

MARKER = "<!-- requirements-check -->"

# Fixed column order for the checks table and detail bullets.
_KIND_ORDER = [
    CheckKind.CI_UPLOAD,
    CheckKind.RELEASE_PIPELINE,
    CheckKind.REPO_PUBLIC,
    CheckKind.PR_LINK,
]

_STATUS_SYMBOL = {
    CheckStatus.PASS: "✅",
    CheckStatus.WARN: "⚠️",
    CheckStatus.FAIL: "❌",
}


def _cell_placeholder(pkg_name: str, kind: CheckKind) -> str:
    """Return the agent cell placeholder for a package/kind."""
    return "{{CHECK_CELL:" + pkg_name + ":" + kind.value + "}}"


def _detail_placeholder(pkg_name: str, kind: CheckKind) -> str:
    """Return the agent detail placeholder for a package/kind."""
    return "{{CHECK_DETAIL:" + pkg_name + ":" + kind.value + "}}"


def _all_pass(result: CheckRunResult) -> bool:
    """Return True when every check on every package passed."""
    return all(
        kind in package.checks and package.checks[kind].status is CheckStatus.PASS
        for package in result.packages
        for kind in _KIND_ORDER
    )


def _table_cell(package: PackageChange, kind: CheckKind) -> str:
    """Return the table cell contents for a package/kind."""
    result = package.checks.get(kind)
    if result is None:
        return "—"
    if result.status is CheckStatus.NEEDS_AGENT:
        return _cell_placeholder(package.name, kind)
    return _STATUS_SYMBOL.get(result.status, "—")


def _detail_bullet(package: PackageChange, kind: CheckKind) -> str:
    """Return the detail bullet line for a package/kind."""
    result = package.checks.get(kind)
    if result is None:
        return f"- **{kind.value}**: — skipped."
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"- **{kind.value}**: {_detail_placeholder(package.name, kind)}"
    symbol = _STATUS_SYMBOL.get(result.status, "")
    return f"- **{kind.value}**: {symbol} {result.details}"


def render_comment(result: CheckRunResult) -> str:
    """Render the requirements-check PR comment for a run result."""
    lines: list[str] = [MARKER, "", "## Requirements supply-chain check", ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        return "\n".join(lines)

    needs_agent = result.needs_agent

    if _all_pass(result):
        lines.append("All requirements checks passed. ✅")
        lines.append("")

    lines.append("<details open>" if needs_agent else "<details>")
    lines.append("<summary>Requirements checks</summary>")
    lines.append("")

    header = ["Package", *(kind.value for kind in _KIND_ORDER)]
    lines.append("| " + " | ".join(header) + " |")
    lines.append("| " + " | ".join(["---"] * len(header)) + " |")
    for package in result.packages:
        row = [package.name]
        row.extend(_table_cell(package, kind) for kind in _KIND_ORDER)
        lines.append("| " + " | ".join(row) + " |")
    lines.append("")

    for package in result.packages:
        version = (
            f"{package.old_version} → {package.new_version}"
            if package.old_version is not None
            else f"(new) {package.new_version}"
        )
        lines.append(f"### `{package.name}` {version}")
        for kind in _KIND_ORDER:
            lines.append(_detail_bullet(package, kind))
        lines.append("")

    lines.append("</details>")
    return "\n".join(lines)
