from __future__ import annotations

from .diff import parse_diff
from .models import (
    CheckKind,
    CheckResult,
    CheckRunResult,
    CheckStatus,
    PackageChange,
)
from .pypi import ProvenanceResult, PypiPackageInfo, check_provenance, fetch_package_info


def _checks_for_missing_package(name: str, version: str) -> dict[CheckKind, CheckResult]:
    """Return checks for a package version that is not present on PyPI."""
    detail = f"Package {name}=={version} was not found on PyPI."
    return {
        CheckKind.CI_UPLOAD: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.RELEASE_PIPELINE: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.REPO_PUBLIC: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.PR_LINK: CheckResult(CheckStatus.FAIL, detail),
    }


def _upload_checks(
    provenance: ProvenanceResult,
) -> dict[CheckKind, CheckResult]:
    """Return CI_UPLOAD and RELEASE_PIPELINE checks based on provenance."""
    if provenance.has_attestation and provenance.recognized_publisher:
        return {
            CheckKind.CI_UPLOAD: CheckResult(
                CheckStatus.PASS,
                "Artifact uploaded with a PEP 740 attestation from a "
                f"recognized publisher ({provenance.publisher_kind}).",
            ),
            CheckKind.RELEASE_PIPELINE: CheckResult(
                CheckStatus.PASS,
                "Release published from a recognized CI pipeline "
                f"({provenance.publisher_kind}).",
            ),
        }

    if provenance.has_attestation and not provenance.recognized_publisher:
        return {
            CheckKind.CI_UPLOAD: CheckResult(
                CheckStatus.WARN,
                "Artifact carries an attestation, but from an unrecognized "
                f"publisher ({provenance.publisher_kind}).",
            ),
            CheckKind.RELEASE_PIPELINE: CheckResult(
                CheckStatus.NEEDS_AGENT,
                "Release pipeline publisher unrecognised; manual review "
                f"required (publisher: {provenance.publisher_kind}).",
            ),
        }

    return {
        CheckKind.CI_UPLOAD: CheckResult(
            CheckStatus.WARN,
            "No PEP 740 provenance attestation was found for this artifact.",
        ),
        CheckKind.RELEASE_PIPELINE: CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No attestation available; release pipeline must be verified manually.",
        ),
    }


def _repo_checks(info: PypiPackageInfo) -> dict[CheckKind, CheckResult]:
    """Return REPO_PUBLIC and PR_LINK checks based on the repo URL."""
    if info.repo_url is None:
        return {
            CheckKind.REPO_PUBLIC: CheckResult(
                CheckStatus.FAIL,
                "Package does not advertise a source repository URL.",
            ),
            CheckKind.PR_LINK: CheckResult(
                CheckStatus.FAIL,
                "No repository URL available to locate a corresponding PR.",
            ),
        }

    return {
        CheckKind.REPO_PUBLIC: CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Verify that the repository at {info.repo_url} is public.",
        ),
        CheckKind.PR_LINK: CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Locate the release PR/commit in {info.repo_url}.",
        ),
    }


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse a diff, fetch PyPI info and run all checks for each package."""
    packages = parse_diff(diff_text)

    for package in packages:
        info = fetch_package_info(package.name, package.new_version)
        package.repo_url = info.repo_url

        if not info.found:
            package.checks = _checks_for_missing_package(
                package.name, package.new_version
            )
            continue

        provenance = check_provenance(info)
        checks: dict[CheckKind, CheckResult] = {}
        checks.update(_upload_checks(provenance))
        checks.update(_repo_checks(info))
        package.checks = checks

    return CheckRunResult(pr_number=pr_number, packages=packages)
